#!/usr/bin/env bash
# Copilot-only PreToolUse guard for Archon build-feature-copilot runs (registered by .github/hooks/archon-run-guard.json;
# Claude Code never reads that file). Why: Archon's copilot provider passes a node's denied_tools to the CLI as excluded
# tool NAMES, so Claude-style `Bash(*--no-verify*)` patterns match nothing there. This hook re-states the safety subset.
# Two layers. (1) An optional .archon/copilot/deny.json (a JSON array of Claude-style deny patterns such as
# `Bash(*--no-verify*)` or `Read(./.env)`, generated by the kit from settings.json permissions.deny; RUN_GUARD_DENY
# overrides the path) is enforced in EVERY session. (2) The run-worktree rules below.
# The run-worktree rules are active ONLY when the session runs inside an Archon run worktree (a path with /.archon/workspaces/ or /.archon/worktrees/,
# or one of RUN_GUARD_MARKERS, colon separated); anywhere else, the owner's own Copilot chat included, it allows everything.
# Inside a run it refuses a shell command that:
#   - holds --no-verify, or is a `git commit` with -n (also in a bundle such as -an);
#   - is a `git push` with a refspec naming a protected branch (main, HEAD:main, :main, refs/heads/main, +main);
#     RUN_GUARD_PROTECTED adds branches (space separated);
#   - changes into the main checkout (`cd <main> &&`, `cd <main>;`) or runs `git -C <main>`; the main checkout is the first
#     entry of `git worktree list --porcelain` run in the session folder (never hard-coded);
#   - names commit-tickets or sync-main;
#   - runs `backlog task` without BACKLOG_CWD= (the close-out node runs it with BACKLOG_CWD, the other nodes never do).
# Input (stdin JSON): Claude names (tool_name, tool_input.command, cwd) or Copilot's (toolName, toolArgs as object or JSON
# string, cwd or workingDirectory). Deny: JSON with permissionDecision "deny" on stdout (top level and in hookSpecificOutput)
# and the reason on stderr with exit 2 (Copilot denies on exit 2). Anything unreadable inside a run is a deny; outside a run
# it is an allow. A deny is final: there is no switch to turn the guard off.
set -uo pipefail

markers="${RUN_GUARD_MARKERS:-/.archon/workspaces/:/.archon/worktrees/}"
in_run() { # in_run <path>: 0 when the path lies inside an Archon run worktree
  local p=$1 m rest=$markers
  [ -n "$p" ] || return 1
  while [ -n "$rest" ]; do
    m=${rest%%:*}; [ "$rest" = "$m" ] && rest="" || rest=${rest#*:}
    [ -n "$m" ] && case "$p/" in *"$m"*) return 0 ;; esac
  done
  return 1
}

payload=$(cat)
deny() { # deny <reason>
  local r="BLOCKED by .archon/copilot/hooks/run-guard.sh: $1"
  if command -v node >/dev/null 2>&1; then
    R="$r" node -e 'const r=process.env.R;console.log(JSON.stringify({permissionDecision:"deny",permissionDecisionReason:r,hookSpecificOutput:{hookEventName:"PreToolUse",permissionDecision:"deny",permissionDecisionReason:r}}))'
  fi
  echo "$r" >&2
  exit 2
}

if ! command -v node >/dev/null 2>&1; then
  in_run "${PWD:-}" && deny "node is not on the PATH, so the guard cannot read the tool call (inside an Archon run it refuses rather than waves it through)"
  exit 0
fi

# shellcheck disable=SC2016  # the node program is single-quoted on purpose
verdict=$(PAYLOAD="$payload" RUN_GUARD_MARKERS="$markers" node -e '
const { execFileSync } = require("child_process");
const markers = (process.env.RUN_GUARD_MARKERS || "").split(":").filter(Boolean);
const inRun = p => !!p && markers.some(m => (p + "/").includes(m));
let o = null;
try { o = JSON.parse(process.env.PAYLOAD || ""); } catch { /* handled below */ }
const dirs = [o && (o.cwd || o.workingDirectory), process.cwd(), process.env.COPILOT_PROJECT_DIR, process.env.CLAUDE_PROJECT_DIR].filter(Boolean);
const run = dirs.some(inRun);
const fs = require("fs"), path = require("path");
// the project root: the hook environment, else the git top level of the session folder, else the folder itself
let root = process.env.CLAUDE_PROJECT_DIR || process.env.COPILOT_PROJECT_DIR || "";
if (!root) { try { root = execFileSync("git", ["-C", dirs[0], "rev-parse", "--show-toplevel"], { encoding: "utf8", stdio: ["ignore", "pipe", "ignore"] }).trim(); } catch { root = dirs[0]; } }
// optional deny list (Claude-style patterns, written by the kit from settings.json permissions.deny): every session
let patterns = [];
const denyFile = process.env.RUN_GUARD_DENY || path.join(root, ".archon", "copilot", "deny.json");
try { const d = JSON.parse(fs.readFileSync(denyFile, "utf8")); if (Array.isArray(d)) patterns = d.filter(x => typeof x === "string"); } catch { /* no list, or not readable: none */ }
if (!run && !patterns.length) { console.log("ALLOW"); process.exit(0); }
if (!o || typeof o !== "object") { console.log(run ? "DENY\tthe hook input is not readable JSON" : "ALLOW"); process.exit(0); }
let tool = String(o.tool_name || o.toolName || "");
// Copilot tool names to Claude names, through the same map the audit uses (.archon/copilot/tools.json)
let toolMap = { view: "Read", create: "Write", edit: "Edit", str_replace_editor: "Edit", grep: "Grep", glob: "Glob" };
try { toolMap = Object.assign(toolMap, JSON.parse(fs.readFileSync(path.join(root, ".archon", "copilot", "tools.json"), "utf8")).tools || {}); } catch { /* built-in names only */ }
const mapped = toolMap[tool.toLowerCase()];
const claudeTool = mapped ? (typeof mapped === "string" ? mapped : mapped.as) : (/^(bash|shell|powershell|run_shell_command|run_in_terminal)$/i.test(tool) ? "Bash" : tool);
let args = o.tool_input !== undefined ? o.tool_input : o.toolArgs;
if (typeof args === "string") { try { args = JSON.parse(args); } catch { args = { command: args }; } }
const isShell = claudeTool === "Bash";
const cmd = args && typeof args === "object" ? (args.command || args.cmd || "") : "";
const target = args && typeof args === "object" ? String(args.file_path || args.path || "") : "";
const globRe = g => new RegExp("^" + g.replace(/:\*$/, "*").replace(/[.+?^${}()|[\]\\]/g, "\\$&").replace(/\*/g, ".*") + "$", "s");
const blocks = (pat, t, val) => { // pat is `Tool` or `Tool(glob)`
  const m = /^([A-Za-z_][\w-]*)(?:\((.*)\))?$/s.exec(pat);
  if (!m || m[1] !== t) return false;
  return m[2] === undefined || m[2] === "" ? true : globRe(m[2].replace(/^\.\//, "")).test(String(val).replace(/^\.\//, ""));
};
for (const pat of patterns) {
  if (blocks(pat, claudeTool, isShell ? cmd : target)) { console.log("DENY\tthe project deny list (.archon/copilot/deny.json) holds " + pat); process.exit(0); }
}
if (!run) { console.log("ALLOW"); process.exit(0); }
if (!isShell) { console.log("ALLOW"); process.exit(0); }
if (typeof cmd !== "string" || !cmd.trim()) { console.log("DENY\tthe shell command is not readable in the hook input"); process.exit(0); }
const deny = why => { console.log("DENY\t" + why); process.exit(0); };

// the main checkout: first entry of `git worktree list --porcelain` in the session folder
let main = process.env.RUN_GUARD_MAIN || "";
if (!main) {
  for (const d of dirs.filter(inRun)) {
    try {
      const out = execFileSync("git", ["-C", d, "worktree", "list", "--porcelain"], { encoding: "utf8", stdio: ["ignore", "pipe", "ignore"] });
      const m = /^worktree (.+)$/m.exec(out);
      if (m) { main = m[1]; break; }
    } catch { /* try the next folder */ }
  }
}
const esc = s => s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
const protectedBranches = ["main"].concat((process.env.RUN_GUARD_PROTECTED || "").split(/\s+/).filter(Boolean));

if (/--no-verify/.test(cmd)) deny("--no-verify skips the commit hooks");
if (/(^|[^A-Za-z0-9_-])(commit-tickets|sync-main)/.test(cmd)) deny("commit-tickets and sync-main write to the main checkout");
if (main) {
  const m = esc(main);
  if (new RegExp("(^|[\\s;&|(])cd\\s+[\"\x27]?" + m + "(/[^\\s;&|\"\x27]*)?[\"\x27]?\\s*(&&|;|\\|\\||$)").test(cmd)) deny("a run never works in the main checkout " + main);
  if (new RegExp("git\\s+(-[A-Za-z]\\s+\\S+\\s+)*-C\\s*[\"\x27]?" + m + "([/\\s\"\x27]|$)").test(cmd)) deny("git -C on the main checkout " + main);
}
for (const seg of cmd.split(/&&|\|\||[;|\n]/)) {
  const t = seg.trim().split(/\s+/);
  const gi = t.indexOf("git");
  if (gi < 0) continue;
  const rest = t.slice(gi + 1);
  if (rest.includes("commit") && rest.some(x => /^-[A-Za-z]*n[A-Za-z]*$/.test(x))) deny("git commit -n skips the commit hooks");
  if (rest.includes("push")) {
    for (const x of rest.slice(rest.indexOf("push") + 1)) {
      const ref = x.replace(/^["\x27]+|["\x27]+$/g, "").replace(/^\+/, "");
      const dst = ref.includes(":") ? ref.slice(ref.lastIndexOf(":") + 1) : ref;
      if (!ref.startsWith("-") && protectedBranches.some(b => dst === b || dst === "refs/heads/" + b)) deny("git push to " + dst + ": a run pushes its own branch only");
    }
  }
}
if (/(^|[^A-Za-z0-9_-])backlog\s+task\b/.test(cmd) && !/BACKLOG_CWD=/.test(cmd)) deny("backlog task without BACKLOG_CWD= (only the close-out node runs it)");
console.log("ALLOW");
' 2>/dev/null) || verdict=$'DENY\tthe guard failed before it could decide'

case "$verdict" in
  ALLOW) exit 0 ;;
  DENY*) deny "${verdict#DENY$'\t'}" ;;
  *) deny "the guard failed before it could decide" ;;
esac
